from collections import deque


def shortest_path_all_keys(grid):
    m, n = len(grid), len(grid[0])
    sr = sc = 0
    total_keys = 0
    for r in range(m):
        for c in range(n):
            ch = grid[r][c]
            if ch == '@':
                sr, sc = r, c
            elif ch.islower():
                total_keys += 1

    all_keys_mask = (1 << total_keys) - 1
    visited = {(sr, sc, 0)}
    queue = deque([(sr, sc, 0, 0)])

    while queue:
        r, c, keys, dist = queue.popleft()
        if keys == all_keys_mask:
            return dist
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if not (0 <= nr < m and 0 <= nc < n):
                continue
            ch = grid[nr][nc]
            if ch == '#':
                continue
            new_keys = keys
            if ch.isupper():
                need = 1 << (ord(ch) - ord('A'))
                if not (keys & need):
                    continue
            if ch.islower():
                new_keys = keys | (1 << (ord(ch) - ord('a')))
            state = (nr, nc, new_keys)
            if state in visited:
                continue
            visited.add(state)
            queue.append((nr, nc, new_keys, dist + 1))

    return -1


if __name__ == "__main__":
    print(shortest_path_all_keys(["@.a.#", "###.#", "b.A.B"]))
    print(shortest_path_all_keys(["@..aA", "..B#.", "....b"]))
    print(shortest_path_all_keys(["@Aa"]))

