import java.util.*;

public class Main {
    static int shortestPathAllKeys(String[] grid) {
        int m = grid.length, n = grid[0].length();
        int sr = 0, sc = 0, totalKeys = 0;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                char ch = grid[r].charAt(c);
                if (ch == '@') { sr = r; sc = c; }
                else if (Character.isLowerCase(ch)) totalKeys++;
            }
        }
        int allKeysMask = (1 << totalKeys) - 1;
        Set<String> visited = new HashSet<>();
        visited.add(sr + "," + sc + ",0");
        Queue<int[]> queue = new LinkedList<>();
        queue.add(new int[]{sr, sc, 0, 0});
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0], c = cur[1], keys = cur[2], dist = cur[3];
            if (keys == allKeysMask) return dist;
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
                char ch = grid[nr].charAt(nc);
                if (ch == '#') continue;
                int newKeys = keys;
                if (Character.isUpperCase(ch)) {
                    int need = 1 << (ch - 'A');
                    if ((keys & need) == 0) continue;
                }
                if (Character.isLowerCase(ch)) {
                    newKeys = keys | (1 << (ch - 'a'));
                }
                String state = nr + "," + nc + "," + newKeys;
                if (visited.contains(state)) continue;
                visited.add(state);
                queue.add(new int[]{nr, nc, newKeys, dist + 1});
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        System.out.println(shortestPathAllKeys(new String[]{"@.a.#", "###.#", "b.A.B"}));
        System.out.println(shortestPathAllKeys(new String[]{"@..aA", "..B#.", "....b"}));
        System.out.println(shortestPathAllKeys(new String[]{"@Aa"}));
    }
}

